const raw = items[0].json;
const payload = raw.body && (Array.isArray(raw.body.alerts) || raw.body.status) ? raw.body : raw;
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
if (!alerts.length) return [];

function hash(value) {
  let h = 2166136261;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}

const seen = {};
const fingerprints = [];
alerts.forEach(function (alert) {
  if (!alert.fingerprint || seen[alert.fingerprint]) return;
  seen[alert.fingerprint] = true;
  fingerprints.push(alert.fingerprint);
});
fingerprints.sort();
const key = hash(fingerprints.join(',') || String(payload.groupKey || 'alert'));

const common = payload.commonLabels || {};
const first = alerts.find(function (alert) { return alert.status === 'firing'; }) || alerts[0];
const labelSource = Object.keys(common).length ? common : (first.labels || {});
const matchers = Object.keys(labelSource).map(function (name) {
  return { name: name, value: String(labelSource[name]), isRegex: false, isEqual: true };
});
if (!matchers.length) return [];

const cards = alerts.map(function (alert) {
  const labels = alert.labels || {};
  const annotations = alert.annotations || {};
  const where = [labels.namespace, labels.pod || labels.node || labels.instance].filter(Boolean).join(' / ');
  const links = {};
  if (alert.generatorURL) links.Prometheus = alert.generatorURL;
  if (annotations.runbook_url) links.Runbook = annotations.runbook_url;
  if (annotations.rancher_url) links.Rancher = annotations.rancher_url;
  if (payload.externalURL) links.Alertmanager = payload.externalURL;
  return {
    status: alert.status || 'firing',
    name: labels.alertname || 'alert',
    summary: annotations.summary || annotations.description || '',
    where: where,
    links: links,
  };
});

return [{ json: { alerts: cards, matchers: matchers, key: key, ownerChatId: 891074228 } }];
